import{_ as a,c as r,o as t,a2 as i}from"./chunks/framework.mqLGQ42V.js";const c=JSON.parse('{"title":"填充与描边 (Fill and Stroke) - Rive 编辑器","description":"基础概念 (Fundamentals) 检查器中的“填充与描边 (Fill and Stroke)”部分允许你添加和修改当前选中对象的填充和描边属性。你可以根据需要创建任意数量的填充或描边。","frontmatter":{"title":"填充与描边 (Fill and Stroke) - Rive 编辑器","description":"基础概念 (Fundamentals) 检查器中的“填充与描边 (Fill and Stroke)”部分允许你添加和修改当前选中对象的填充和描边属性。你可以根据需要创建任意数量的填充或描边。","head":[["meta",{"name":"keywords","content":"Rive, Rive 中文文档, Rive 编辑器, 基础概念, 填充与描边"}]]},"headers":[],"relativePath":"editor/fundamentals/fill-and-stroke.md","filePath":"editor/fundamentals/fill-and-stroke.md","lastUpdated":1774838907000}'),l={name:"editor/fundamentals/fill-and-stroke.md"};function o(n,e,s,h,g,p){return t(),r("div",null,[...e[0]||(e[0]=[i('<p>基础概念 (Fundamentals)</p><h1 id="填充与描边-fill-and-stroke" tabindex="-1">填充与描边 (Fill and Stroke) <a class="header-anchor" href="#填充与描边-fill-and-stroke" aria-label="Permalink to &quot;填充与描边 (Fill and Stroke)&quot;">​</a></h1><p>检查器中的“填充与描边 (Fill and Stroke)”部分允许你添加和修改当前选中对象的填充和描边属性。你可以根据需要创建任意数量的填充或描边。</p><h1 id="​-填充-fill" tabindex="-1"><a href="#fill">​</a> 填充 (Fill) <a class="header-anchor" href="#​-填充-fill" aria-label="Permalink to &quot;[​](#fill) 填充 (Fill)&quot;">​</a></h1><h3 id="​-创建新填充" tabindex="-1"><a href="#create-a-new-fill">​</a> <strong>创建新填充</strong> <a class="header-anchor" href="#​-创建新填充" aria-label="Permalink to &quot;[​](#create-a-new-fill) **创建新填充**&quot;">​</a></h3><p>要创建填充，请先选择一个形状，然后使用检查器“填充与描边”部分下的加号按钮。在弹出菜单中选择“Fill”。你可以通过左侧的颜色方块识别出该层是一个填充层。 <img src="https://help.rive.app/images/newFill.gif" alt="新建填充 GIF"></p><h3 id="​-更改填充颜色" tabindex="-1"><a href="#changing-fill-color">​</a> <strong>更改填充颜色</strong> <a class="header-anchor" href="#​-更改填充颜色" aria-label="Permalink to &quot;[​](#changing-fill-color) **更改填充颜色**&quot;">​</a></h3><p>点击填充层左侧的颜色方块即可打开“拾色器 (Color Picker)”。你可以通过各种滑块选择你想要的填充颜色。 <img src="https://help.rive.app/images/changecolor.gif" alt="更改颜色 GIF"></p><h3 id="​-更改填充类型" tabindex="-1"><a href="#changing-fill-type">​</a> <strong>更改填充类型</strong> <a class="header-anchor" href="#​-更改填充类型" aria-label="Permalink to &quot;[​](#changing-fill-type) **更改填充类型**&quot;">​</a></h3><p>创建新形状时，默认使用纯色填充。添加新填充时，默认类型为线性渐变。你可以通过点击颜色方块来切换填充类型。 <img src="https://help.rive.app/images/changefilltype.gif" alt="更改填充类型 GIF"> 在打开的填充窗口顶部，你会发现填充类型下拉菜单。可供选择的填充类型包括：</p><ul><li><strong>Solid (纯色)</strong></li><li><strong>Linear Gradient (线性渐变)</strong></li><li><strong>Radial Gradient (径向渐变)</strong></li></ul><h3 id="​-更改填充颜色-渐变" tabindex="-1"><a href="#changing-fill-color-gradient">​</a> <strong>更改填充颜色 (渐变)</strong> <a class="header-anchor" href="#​-更改填充颜色-渐变" aria-label="Permalink to &quot;[​](#changing-fill-color-gradient) **更改填充颜色 (渐变)**&quot;">​</a></h3><p>当选择渐变类型时，拾色器上方会出现一个长条。它代表了渐变在不同位置的颜色。 <img src="https://help.rive.app/images/changestopper.gif" alt="更改渐变控制点 GIF"></p><h3 id="​-添加和删除控制点" tabindex="-1"><a href="#adding-and-removing-stoppers">​</a> <strong>添加和删除控制点</strong> <a class="header-anchor" href="#​-添加和删除控制点" aria-label="Permalink to &quot;[​](#adding-and-removing-stoppers) **添加和删除控制点**&quot;">​</a></h3><p>点击渐变条上任何没有控制点的位置即可生成新的控制点。 <img src="https://help.rive.app/images/add_remove.gif" alt="添加删除控制点 GIF"> 要删除控制点，先选中它，然后按 <code>Delete</code> 或 <code>Backspace</code> 键。</p><h3 id="​-更改填充顺序" tabindex="-1"><a href="#change-fill-order">​</a> <strong>更改填充顺序</strong> <a class="header-anchor" href="#​-更改填充顺序" aria-label="Permalink to &quot;[​](#change-fill-order) **更改填充顺序**&quot;">​</a></h3><p>填充在列表中的顺序决定了它们的渲染顺序：顶部的填充渲染在最前面，底部的渲染在最后面。 <img src="https://help.rive.app/images/fillOrder.gif" alt="填充顺序 GIF"> 你可以直接在图层区域点击并拖动来更改顺序。</p><h3 id="​-填充属性" tabindex="-1"><a href="#fill-properties">​</a> <strong>填充属性</strong> <a class="header-anchor" href="#​-填充属性" aria-label="Permalink to &quot;[​](#fill-properties) **填充属性**&quot;">​</a></h3><p>每个填充都有自己的属性，可以在时间轴上进行编辑和设置关键帧。点击填充选项按钮可查看更多： <img src="https://help.rive.app/images/fillProp.png" alt="填充属性面板"></p><ul><li><strong>名称 (Name)</strong>：重命名填充。</li><li><strong>混合 (Blend)</strong>：更改单个填充层的混合模式。默认继承自形状层。</li><li><strong>填充规则 (Fill Rule)</strong>：选择填充算法（Non-Zero, Even-Odd, Clockwise）。</li><li><strong>羽化 (Feather)</strong>：启用后可对填充进行羽化效果处理。</li></ul><hr><h1 id="​-描边-stroke" tabindex="-1"><a href="#stroke">​</a> 描边 (Stroke) <a class="header-anchor" href="#​-描边-stroke" aria-label="Permalink to &quot;[​](#stroke) 描边 (Stroke)&quot;">​</a></h1><h3 id="​-创建新描边" tabindex="-1"><a href="#create-a-new-stroke">​</a> 创建新描边 <a class="header-anchor" href="#​-创建新描边" aria-label="Permalink to &quot;[​](#create-a-new-stroke) 创建新描边&quot;">​</a></h3><p>选择形状，点击加号按钮并选择“Stroke”。描边层在左侧通过一个带轮廓的方块来表示。 <img src="https://help.rive.app/images/NewStroke.gif" alt="新建描边 GIF"></p><h3 id="​-更改描边类型" tabindex="-1"><a href="#changing-stroke-type">​</a> <strong>更改描边类型</strong> <a class="header-anchor" href="#​-更改描边类型" aria-label="Permalink to &quot;[​](#changing-stroke-type) **更改描边类型**&quot;">​</a></h3><p>与填充类似，描边也可以设置为纯色、线性渐变或径向渐变。 <img src="https://help.rive.app/images/ChangeStrokeType.gif" alt="更改描边类型 GIF"></p><h1 id="​-描边属性-stroke-properties" tabindex="-1"><a href="#stroke-properties">​</a> 描边属性 (Stroke Properties) <a class="header-anchor" href="#​-描边属性-stroke-properties" aria-label="Permalink to &quot;[​](#stroke-properties) 描边属性 (Stroke Properties)&quot;">​</a></h1><p>每个描边都有独特的属性，点击描边选项按钮可进行设置：</p><ul><li><strong>名称 (Name)</strong></li><li><strong>端点 (Cap)</strong>：更改描边末端的形状。 <ul><li><strong>Butt (平头)</strong>：在端点处平齐，不延伸。</li><li><strong>Round (圆头)</strong>：半圆形端点。在零长度路径上表现为一个圆。</li><li><strong>Square (方头)</strong>：方形端点，延伸出端点一段距离。</li></ul></li><li><strong>连接 (Join)</strong>：更改路径转角处的渲染方式。 <ul><li><strong>Round (圆角)</strong></li><li><strong>Bevel (斜角)</strong></li><li><strong>Miter (直角/尖角)</strong></li></ul></li><li><strong>应用变换 (Apply Transformations)</strong>：确定形状的“缩放”是否会改变描边的粗细。关闭后，粗细将保持恒定（非缩放）。</li><li><strong>羽化 (Feather)</strong>：开启矢量羽化。</li><li><strong>描边类型 (Stroke Type)</strong>： <ul><li><strong>Solid (实线)</strong>：默认类型。</li><li><strong>Trim (路径裁剪)</strong>：允许动画化起始点、终点和偏移。详见<a href="/docs/editor/manipulating-shapes/trim-path">路径裁剪</a>。</li><li><strong>Dashed (虚线)</strong>：允许设置虚线长度和间隙。</li></ul></li></ul><hr><h1 id="​-矢量羽化-vector-feathering" tabindex="-1"><a href="#vector-feathering">​</a> 矢量羽化 (Vector Feathering) <a class="header-anchor" href="#​-矢量羽化-vector-feathering" aria-label="Permalink to &quot;[​](#vector-feathering) 矢量羽化 (Vector Feathering)&quot;">​</a></h1><p>矢量羽化是 Rive 发明的一项新技术，可以柔化矢量路径的边缘，而不会像传统的模糊效果那样产生沉重的性能负担。</p><h3 id="​-启用矢量羽化" tabindex="-1"><a href="#enabling-vector-feathering">​</a> <strong>启用矢量羽化</strong> <a class="header-anchor" href="#​-启用矢量羽化" aria-label="Permalink to &quot;[​](#enabling-vector-feathering) **启用矢量羽化**&quot;">​</a></h3><p>你可以通过填充或描边层上的羽化图标，或者在选项面板中的开关来开启。 <img src="https://help.rive.app/images/EnableFeather.gif" alt="启用羽化 GIF"></p><h3 id="​-羽化选项" tabindex="-1"><a href="#feathering-options">​</a> 羽化选项 <a class="header-anchor" href="#​-羽化选项" aria-label="Permalink to &quot;[​](#feathering-options) 羽化选项&quot;">​</a></h3><ul><li><strong>方向 (Direction)</strong>：选择向内 (Inner) 或向外 (Outer) 产生羽化。 <img src="https://help.rive.app/images/Direction.gif" alt="方向 GIF"></li><li><strong>数值 (Amount)</strong>：控制羽化的强度。</li><li><strong>空间 (Space)</strong>： <ul><li><strong>World (世界空间)</strong>：羽化表现更接近投影效果。</li><li><strong>Local (局部空间)</strong>：羽化随变换对象一起运作。</li></ul></li><li><strong>偏移 (Offset)</strong>：控制羽化效果在 X 和 Y 轴上的偏移量。</li></ul><p><a href="https://help.rive.app/editor/fundamentals/group-tips" target="_blank" rel="noreferrer">分组技巧 (Group Tips)</a><a href="https://help.rive.app/editor/fundamentals/edit-vertices" target="_blank" rel="noreferrer">编辑顶点 (Edit Vertices)</a></p>',37)])])}const f=a(l,[["render",o]]);export{c as __pageData,f as default};
